import {esc,icon,cats,statusLabels,statusBadge,date,photo,entryCard,api,post} from './components.js';
import {site,siteUrl,routePath} from './site-config.js';
import {mixEntries,mountCarousels} from './carousels.js';
let data={provinces:[],entries:[]}, user=null, notifications=[], requestCache=[], pageVersion=0;
const app=document.querySelector('#app'), dialog=document.querySelector('#auth-dialog');
const province=id=>data.provinces.find(p=>p.id===id);
const route=(url)=>{history.pushState({},'',siteUrl(url));render();window.scrollTo({top:0,behavior:'instant'})};
const button=(label,href,cls='btn-primary',ico='arrow')=>`<a class="btn ${cls}" href="${esc(href)}">${site.publicPreview&&href.startsWith('/request')?'Request belum dibuka':label}${icon(ico)}</a>`;
const surfaceIcon=(name,tone='')=>`<span class="surface-icon ${tone}">${icon(name)}</span>`;
const crumb=(items)=>`<nav class="breadcrumbs" aria-label="Jejak halaman"><a href="/">Beranda</a>${items.map(([name,url])=>`${icon('chevron')}${url?`<a href="${esc(url)}">${esc(name)}</a>`:`<span aria-current="page">${esc(name)}</span>`}`).join('')}</nav>`;
const notice=(text,cls='')=>`<div class="notice ${cls}">${icon('info')}<p>${text}</p></div>`;
const empty=(title,text,link='',label='Ajukan request')=>`<div class="empty-state">${icon('leaf')}<h3>${title}</h3><p>${text}</p>${link?button(label,link,'btn-outline'):''}</div>`;
const formError=()=>'<p class="form-error" role="alert" hidden></p>';
const getValues=form=>Object.fromEntries(new FormData(form));
const requestLink=(pid='',cat='')=>`/request?provinsi=${encodeURIComponent(pid)}&kategori=${encodeURIComponent(cat)}`;
function preparePageLinks(){if(!site.basePath)return;document.querySelectorAll('a[href^="/"],img[src^="/"]').forEach(el=>{const attr=el.tagName==='IMG'?'src':'href';el.setAttribute(attr,siteUrl(el.getAttribute(attr)))});}
function publicFeaturePage(name='Request'){return `<section class="wrap account-page">${crumb([[name]])}<div class="page-heading"><span class="eyebrow">PRATINJAU PUBLIK</span><h1>${name==='Akun'?'Akun belum tersedia.':'Request belum dibuka.'}</h1><p>Kamu bisa membaca koleksi budaya dan membuka sumber rujukannya. Pengelola belum membuka pendaftaran akun dan pengiriman request pada situs publik ini.</p></div>${notice('Materi masih dalam tahap pengisian. Versi publik ini belum menerima kebutuhan belajar atau data pribadi pengunjung.')}${button('Pilih provinsi','/#provinsi','btn-dark')}</section>`}
const formatRole=role=>({admin:'Pengelola',expert:'Pendamping',user:'Pengunjung'}[role]||'Pengunjung');

function navigationProvince(){const parts=routePath(location.pathname).split('/');return province(parts[1]==='provinsi'?parts[2]:parts[1]==='materi'?data.entries.find(e=>e.id===parts[2])?.provinceId:'sumatera-barat')||province('sumatera-barat');}
function header(){
 const selected=navigationProvince(),pid=selected?.id||'sumatera-barat';
 const regions=data.provinces.map((p,i)=>`<a class="nav-region-link" href="/provinsi/${esc(p.id)}"><span>${esc(p.name)}<small>${esc(p.capital)}</small></span>${icon('upRight')}</a>`).join('');
 const learning=[['tari','Tari','Kenali gerak dan latar pertunjukan.','book'],['musik','Musik tradisional','Baca tentang bunyi dan alatnya.','music'],['kerajinan','Kerajinan','Kenali bahan dan keterampilannya.','leaf'],['wisata','Wisata & ikon','Baca cerita di balik tempatnya.','pin'],['kuliner','Kuliner','Kenali makanan dan kebiasaan setempat.','bowl'],['permainan','Permainan','Baca pengenalan dan panduannya.','game']].map(([id,title,detail,ico])=>`<a href="/provinsi/${pid}?tab=${['tari','musik','kerajinan'].includes(id)?'seni&jenis='+id:id}">${icon(ico)}<span>${title}<small>${detail}</small></span>${icon('upRight')}</a>`).join('');
 const auth=user?`<a class="icon-btn notification-link" href="/akun?bagian=notifikasi" aria-label="Notifikasi${notifications.some(n=>!n.read)?', ada yang belum dibaca':''}">${icon('bell')}${notifications.some(n=>!n.read)?'<i class="notification-dot"></i>':''}</a><a class="account-link" href="/akun"><span class="avatar">${esc(user.name.charAt(0))}</span><span>${esc(user.name.split(' ')[0])}</span></a>`:site.publicPreview?'<a class="login-link" href="/tentang#batas-layanan">Pratinjau</a>':`<button class="login-link" data-auth>Masuk ${icon('user')}</button>`;
 return `<header class="site-header"><div class="nav-inner"><a class="brand" href="/" aria-label="SwaraNusa, beranda"><span class="brand-emblem">S<span></span></span><span>Swara<span class="brand-nusa">Nusa</span><small>WARISAN BUDAYA SUMATERA</small></span></a><nav class="desktop-nav" aria-label="Navigasi utama"><div class="nav-dropdown"><button class="nav-dropdown-toggle" data-nav-dropdown aria-expanded="false" aria-controls="province-dropdown">Jelajahi daerah ${icon('chevron','chevron-icon')}</button><div class="nav-dropdown-panel" id="province-dropdown" popover="manual" hidden><div class="mega-menu-header"><span class="eyebrow">MULAI DARI DAERAH</span><h2>Mau mengenal provinsi mana?</h2><p>Sumatra dan kepulauan di sekitarnya.</p></div><div class="nav-province-grid">${regions}</div><a class="nav-dropdown-footer" href="/#provinsi">Lihat pilihan di beranda ${icon('arrow')}</a></div></div><div class="nav-dropdown"><button class="nav-dropdown-toggle" data-nav-dropdown aria-expanded="false" aria-controls="learning-dropdown">Belajar budaya ${icon('chevron','chevron-icon')}</button><div class="nav-dropdown-panel" id="learning-dropdown" popover="manual" hidden><div class="mega-menu-header"><span class="eyebrow">${esc(selected?.name.toUpperCase())}</span><h2>Mulai dari yang kamu suka.</h2><p>Materi untuk ${esc(selected?.name)}. Ganti daerah lewat menu Jelajahi daerah.</p></div><div class="nav-learn-links">${learning}</div><a class="nav-dropdown-footer" href="/tentang#belajar">Cara belajar di SwaraNusa ${icon('arrow')}</a></div></div><a href="/tentang">Tentang</a></nav><div class="nav-actions">${auth}<button class="icon-btn mobile-menu" data-menu aria-label="Buka menu" aria-expanded="false" aria-controls="mobile-navigation">${icon('menu')}</button></div></div><nav class="mobile-nav" id="mobile-navigation" hidden aria-label="Navigasi ponsel"><details><summary>Jelajahi daerah ${icon('chevron','chevron-icon')}</summary><div class="mobile-submenu">${regions}</div></details><details><summary>Belajar budaya ${icon('chevron','chevron-icon')}</summary><p class="mobile-context">Materi untuk ${esc(selected?.name)}.</p><div class="mobile-submenu">${learning}</div></details><a href="/tentang">Tentang SwaraNusa</a><a href="/pendamping">Pendamping</a><a href="/request">${site.publicPreview?'Tentang request':'Ajukan request'}</a></nav></header>`;
}
function closeNavDropdowns(restore=false){let trigger;document.querySelectorAll('[data-nav-dropdown][aria-expanded="true"]').forEach(button=>{trigger=button;button.setAttribute('aria-expanded','false');const panel=document.getElementById(button.getAttribute('aria-controls'));if(panel){if(typeof panel.hidePopover==='function'&&panel.matches(':popover-open'))panel.hidePopover();panel.hidden=true;}});if(restore)trigger?.focus();}
function toggleNavDropdown(button,focusFirst=false){
 const open=button.getAttribute('aria-expanded')!=='true';closeNavDropdowns();button.setAttribute('aria-expanded',String(open));
 const panel=document.getElementById(button.getAttribute('aria-controls'));if(!panel)return;panel.hidden=!open;
 if(open){
  if(typeof panel.showPopover==='function'){
   panel.classList.add('native-popover');panel.showPopover();
   const anchor=button.getBoundingClientRect(),width=panel.getBoundingClientRect().width;
   panel.style.setProperty('--popover-left',Math.max(16,Math.min(anchor.left+anchor.width/2-width/2,innerWidth-width-16))+'px');
   panel.style.setProperty('--popover-top',anchor.bottom+12+'px');
  }
  if(focusFirst)panel.querySelector('a')?.focus();
 }
}

function closeMobileMenu(restore=false){const menu=document.querySelector('.mobile-nav'),trigger=document.querySelector('[data-menu]');if(menu)menu.hidden=true;if(trigger){trigger.setAttribute('aria-expanded','false');trigger.setAttribute('aria-label','Buka menu');if(restore)trigger.focus();}}
let revealObserver, disposeCarousels=()=>{}, mixedHomeEntries;
function setupMotion(){
 revealObserver?.disconnect();
 if(matchMedia('(prefers-reduced-motion: reduce)').matches||!('IntersectionObserver' in window))return;
 document.querySelector('.hero-content')?.classList.add('hero-entrance');
 revealObserver=new IntersectionObserver(records=>{for(const record of records){if(record.isIntersecting){record.target.classList.add('is-visible');revealObserver.unobserve(record.target);}}},{threshold:0.08,rootMargin:'0px 0px -24px 0px'});
 document.querySelectorAll('.start-guide,.section-heading,.province-carousel,.culture-carousel,.province-row,.entry-card,.request-band,.province-hero-copy,.province-hero-photo,.article-header,.about-heading,.about-columns>section,.about-side-stack>section').forEach((el,i)=>{if(el.closest('[data-carousel]')!==el&&el.closest('[data-carousel]'))return;if(el.getBoundingClientRect().top>window.innerHeight*0.95){el.classList.add('reveal-pending');el.style.setProperty('--reveal-delay',`${Math.min(i%3,2)*45}ms`);revealObserver.observe(el);}});
}

function footer(){return `<footer class="site-footer"><div class="footer-top"><div><a class="footer-brand" href="/">SwaraNusa</a><p>Pengenalan budaya Sumatra<br>dan kepulauan sekitarnya.</p></div><div><h3>Mulai dari sini</h3><a href="/#provinsi">Pilih provinsi</a><a href="/pendamping">Cari pendamping</a><a href="/request">${site.publicPreview?'Tentang request':'Ajukan request'}</a></div><div><h3>Tentang SwaraNusa</h3><a href="/tentang">Cerita dan tujuan</a><a href="/tentang#sumber">Sumber & kredit foto</a><a href="/tentang#bantuan">Koreksi informasi</a></div><div class="footer-note"><span class="small-label">EDISI PERTAMA</span><p>Sumatra dan kepulauan sekitarnya.</p><span class="footer-seal">10 PROVINSI ${icon('spark')}</span></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} SwaraNusa</span><span>Proyek pembelajaran pemrograman web</span><a href="/tentang#batas-layanan">Batas layanan ${icon('upRight')}</a></div></footer>`}
function carouselCaption(label,total){return `<div class="carousel-caption"><span class="carousel-count" data-carousel-count>01 / ${String(total).padStart(2,'0')}</span><span class="carousel-hint">Geser untuk melihat ${label==='banner'?'daerah':label} lainnya</span><span class="visually-hidden" aria-live="polite" data-carousel-announcement></span></div>`;}
function heroCarousel(){
 const places={aceh:['MASJID RAYA BAITURRAHMAN','Banda Aceh, Aceh'],'sumatera-utara':['DANAU TOBA','Sumatera Utara'],'sumatera-barat':['ISTANO BASA PAGARUYUNG','Tanah Datar, Sumatera Barat'],riau:['ISTANA SIAK SRI INDRAPURA','Siak, Riau'],'kepulauan-riau':['PULAU PENYENGAT','Tanjungpinang, Kepulauan Riau'],jambi:['KAWASAN CANDI MUARAJAMBI','Muaro Jambi, Jambi'],bengkulu:['BENTENG MARLBOROUGH','Kota Bengkulu'],'sumatera-selatan':['JEMBATAN AMPERA','Palembang, Sumatera Selatan'],'bangka-belitung':['PANTAI TANJUNG TINGGI','Belitung, Kepulauan Bangka Belitung'],lampung:['MENARA SIGER','Bakauheni, Lampung']};
 return `<section class="home-hero hero-carousel" data-carousel role="region" aria-roledescription="karusel" aria-labelledby="hero-title"><div class="hero-track" data-carousel-track tabindex="0" aria-label="Geser foto daerah ke samping">${data.provinces.map((p,i)=>`<div class="hero-slide" data-slide-id="${esc(p.id)}" data-slide-label="${esc(places[p.id][0])}, ${esc(p.name)}" role="group" aria-roledescription="slide" aria-label="${i+1} dari ${data.provinces.length}: ${esc(p.name)}"><img class="hero-image" src="${esc(p.image)}" alt="${esc(p.imageAlt)}" ${i===0?'fetchpriority="high"':'loading="lazy"'} draggable="false"><div class="hero-shade"></div><a class="hero-location" href="/provinsi/${esc(p.id)}">${icon('pin')}<span>${esc(places[p.id][0])}<small>${esc(places[p.id][1])}</small></span>${icon('upRight')}</a></div>`).join('')}</div><div class="hero-content"><span class="eyebrow light"><i></i> CATATAN DARI SUMATRA</span><h1 id="hero-title">Kenali budaya<br><em>Sumatra.</em></h1><p>Mulai dari daerah yang ingin kamu kenal.<br> Baca cerita budayanya, lalu pilih yang ingin kamu pelajari.</p><div class="hero-actions">${button('Pilih provinsi','/#provinsi','btn-cream')}<a class="text-link light" href="/tentang">Tentang SwaraNusa ${icon('upRight')}</a></div></div>${carouselCaption('banner',data.provinces.length)}<div class="hero-bottom"><span>ACEH <i></i> LAMPUNG <i></i> KEPULAUAN SEKITARNYA</span><a href="/#provinsi">Gulir untuk memilih daerah <span>↓</span></a></div></section>`;
}
function home(){
 const featured=mixedHomeEntries??=mixEntries(data.entries,data.provinces);
 const provinceTeasers={aceh:'Kenali Saman dan cerita di Banda Aceh.','sumatera-utara':'Baca tentang ulos dan daerah di sekitar Danau Toba.','sumatera-barat':'Kenali seni dan keseharian masyarakat Minangkabau.',riau:'Temui tradisi Melayu di Siak dan sekitarnya.','kepulauan-riau':'Kenali seni dan jejak sejarah di Pulau Penyengat.',jambi:'Baca tentang batik dan kawasan Candi Muarajambi.',bengkulu:'Kenali musik dol dan jejak sejarah Kota Bengkulu.','sumatera-selatan':'Baca cerita Palembang, dari Ampera sampai pempek.','bangka-belitung':'Kenali dambus dan pesisir Bangka Belitung.',lampung:'Baca tentang tapis dan kebiasaan makan bersama.'};
 return `${heroCarousel()}
 <section class="start-guide wrap" aria-label="Mulai mengenal budaya"><div class="start-guide-intro"><span class="eyebrow">BARU DI SWARANUSA?</span><h2>Mulai dari<br>yang ingin kamu kenal.</h2><a class="text-link" href="/tentang#belajar">Cara belajarnya ${icon('arrow')}</a></div><div class="start-guide-links">${[['compass','01','Pilih daerah','Dari Aceh sampai Lampung.','/#provinsi'],['book','02','Temukan topik','Seni, wisata, kuliner, atau permainan.','/#bacaan'],['globe','03','Baca rujukannya','Kenali cerita dan sumber budayanya.','/tentang#sumber']].map(([ico,n,title,copy,href])=>`<a class="guide-link" href="${href}"><div class="guide-link-top">${surfaceIcon(ico)}<span>${n}</span></div><h3>${title}${icon('upRight')}</h3><p>${copy}</p></a>`).join('')}</div></section>
 <section class="province-section wrap" id="provinsi"><div class="section-heading"><div><span class="eyebrow label-pill">${icon('compass')} 01 / PILIH DAERAH</span><h2>Mulai dari<br><em>satu provinsi.</em></h2></div><p>Pilih satu dari 10 provinsi di wilayah Sumatra.<br>Kamu bisa berganti daerah kapan saja.</p></div><div class="province-layout"><div class="province-carousel" data-carousel role="region" aria-roledescription="karusel" aria-label="Sorotan provinsi">${carouselCaption('provinsi',data.provinces.length)}<div class="province-track" data-carousel-track tabindex="0" aria-label="Geser pilihan provinsi ke samping">${data.provinces.map((p,i)=>`<div class="province-slide" data-slide-id="${esc(p.id)}" data-slide-label="${esc(p.name)}" role="group" aria-roledescription="slide" aria-label="${i+1} dari ${data.provinces.length}: ${esc(p.name)}"><a class="province-feature" href="/provinsi/${esc(p.id)}">${photo(p)}<div class="province-feature-shade"></div><span class="region-tag">KENALI DAERAH</span><div class="province-feature-content"><span>${String(i+1).padStart(2,'0')} / ${esc(p.name.toUpperCase())}</span><h3>${esc(provinceTeasers[p.id]||p.description)}</h3><span class="feature-cta">Kenali ${esc(p.name)} ${icon('arrow')}</span></div></a></div>`).join('')}</div></div><div class="province-index"><div class="province-index-heading">${surfaceIcon('compass')}<div><span class="eyebrow">${data.provinces.length} PROVINSI</span><h3>Pilih daerahmu.</h3></div></div><div class="province-list">${data.provinces.map((p,i)=>`<a class="province-row" href="/provinsi/${esc(p.id)}"><span class="province-number">${String(i+1).padStart(2,'0')}</span><span class="province-row-name">${esc(p.name)}<small>${esc(p.capital)}</small></span>${icon('upRight')}</a>`).join('')}</div></div></div></section>
 <section class="culture-section" id="bacaan"><div class="wrap"><div class="section-heading"><div><span class="eyebrow label-pill">${icon('book')} 02 / KENALI DAN PELAJARI</span><h2>Baca pengenalan<br><em>budaya setempat.</em></h2></div><a class="text-link" href="/#provinsi">Pilih daerah yang ingin kamu baca ${icon('arrow')}</a></div><div class="culture-carousel" data-carousel role="region" aria-roledescription="karusel" aria-label="Bacaan budaya pilihan">${carouselCaption('bacaan',featured.length)}<div class="culture-track" data-carousel-track tabindex="0" aria-label="Geser bacaan budaya ke samping">${featured.map((e,i)=>`<div class="culture-slide" data-slide-id="${esc(e.id)}" data-slide-label="${esc(e.title)}, ${esc(province(e.provinceId)?.name)}" role="group" aria-roledescription="slide" aria-label="${i+1} dari ${featured.length}: ${esc(e.title)}">${entryCard(e,data.provinces)}</div>`).join('')}</div></div></div></section>
 <section class="request-band wrap"><div class="request-band-art" aria-hidden="true"><img src="/assets/sumatra-silhouette.svg" alt="" width="300" height="300" loading="lazy"></div><div><span class="eyebrow">PUNYA TOPIK LAIN?</span><h2>Belum ketemu<br>yang kamu cari?</h2><p>${site.publicPreview?'Koleksi ini masih dalam tahap pengisian. Kamu bisa membaca materi yang tersedia dan rujukan pada setiap artikel.':'Sebutkan materi yang ingin kamu baca atau pendamping yang kamu butuhkan. Pengelola akan meninjau request kamu.'}</p>${button(site.publicPreview?'Tentang koleksi':'Ajukan request',site.publicPreview?'/tentang#batas-layanan':'/request','btn-dark')}</div><span class="band-note">${surfaceIcon('book','gold')}${site.publicPreview?'Materi masih dalam tahap pengisian.<br>Kami melengkapinya secara bertahap.':'Koleksi kami masih bertumbuh.<br>Usulanmu membantu memilih materi berikutnya.'}</span></section>`
}
function provincePage(pid,params){
 const p=province(pid);if(!p)return notFound();
 const tab=params.get('tab')||'seni', kind=params.get('jenis')||'semua';
 const options=[['seni','Belajar Seni','book'],['wisata','Wisata & Ikon','pin'],['kuliner','Kuliner','bowl'],['permainan','Permainan Tradisional','game']];
 const valid=options.some(o=>o[0]===tab)?tab:'seni';
 const entries=data.entries.filter(e=>e.provinceId===pid&&(valid==='seni'?['tari','musik','kerajinan'].includes(e.category):e.category===valid)&&(valid!=='seni'||kind==='semua'||e.category===kind));
 const titles={seni:['Belajar seni dari daerahnya.','Kenali latar budayanya sebelum mengikuti materi praktik.'],wisata:['Tempat dan cerita di sekitarnya.','Baca konteks tempatnya untuk menyiapkan kunjungan.'],kuliner:['Kenali daerah lewat makanannya.','Baca bahan utama dan kebiasaan masyarakat menyajikannya.'],permainan:['Siapkan alatnya. Ajak temanmu.','Kenali permainan dan baca aturan sebelum mencoba.']};
 return `<div class="wrap">${crumb([[p.name]])}</div><section class="province-hero wrap"><div class="province-hero-copy"><span class="eyebrow">SUMATRA / ${esc(p.capital.toUpperCase())}</span><h1>${esc(p.name)}</h1><p>${esc(p.description)}</p><a class="text-link" href="/#provinsi">${icon('back')} Ganti provinsi</a></div><div class="province-hero-photo">${photo(p,'',true)}<span class="image-caption">${icon('pin')} ${esc(p.imageAlt||p.name)}</span></div></section><div class="category-nav-shell"><nav class="category-nav wrap" aria-label="Kategori di ${esc(p.name)}">${options.map(([id,label,ico])=>`<a class="${valid===id?'active':''}" href="/provinsi/${pid}?tab=${id}" ${valid===id?'aria-current="page"':''}>${icon(ico)}${label}</a>`).join('')}</nav></div><section class="collection wrap"><div class="collection-title"><div><span class="eyebrow">KOLEKSI / ${esc(p.name.toUpperCase())}</span><h2>${titles[valid][0]}</h2><p>${titles[valid][1]}</p></div><span class="collection-count">${entries.length} materi tersedia</span></div>${valid==='seni'?`<nav class="filter-nav" aria-label="Jenis seni">${[['semua','Semua seni'],['tari','Tari'],['musik','Musik tradisional'],['kerajinan','Kerajinan']].map(([id,label])=>`<a class="filter ${kind===id?'active':''}" href="/provinsi/${pid}?tab=seni&jenis=${id}" ${kind===id?'aria-current="true"':''}>${label}</a>`).join('')}</nav>`:''}${entries.length?`<div class="collection-grid">${entries.map(e=>entryCard(e,data.provinces)).join('')}</div>`:empty('Materinya sedang kami siapkan.',site.publicPreview?'Kamu bisa membuka kategori lain untuk membaca materi yang tersedia.':'Kamu bisa membuka kategori lain atau mengusulkan topik yang ingin kamu pelajari.',requestLink(pid,valid==='seni'&&kind!=='semua'?kind:valid==='seni'?'tari':valid))}<div class="collection-request"><div><h3>Punya topik yang belum ada di sini?</h3><p>${site.publicPreview?'Pengiriman request belum dibuka pada pratinjau publik ini.':'Tulis kebutuhanmu agar pengelola dapat meninjaunya.'}</p></div>${button('Ajukan request',requestLink(pid,valid==='seni'?(kind!=='semua'&&cats[kind]?kind:'tari'):valid),'btn-outline')}</div></section>`;
}
function entryPage(id){
 const e=data.entries.find(e=>e.id===id);if(!e)return notFound();const p=province(e.provinceId);
 const imageCredit=data.photos?.find(p=>p.path===e.image);
 const related=data.entries.filter(x=>x.provinceId===e.provinceId&&x.id!==id).slice(0,3);
 return `<article class="entry-page"><div class="wrap">${crumb([[p?.name,`/provinsi/${e.provinceId}`],[cats[e.category],`/provinsi/${e.provinceId}?tab=${['tari','musik','kerajinan'].includes(e.category)?'seni':e.category}`],[e.title]])}<header class="article-header"><span class="eyebrow">${esc(cats[e.category])} / ${esc(e.kind||'Pengenalan')}</span><h1>${esc(e.title)}</h1><p>${esc(e.subtitle||e.summary)}</p><div class="article-meta">${icon('pin')}${esc(e.location||p?.name)}<span>·</span>${esc(e.community||p?.name)}</div></header><figure class="article-figure">${photo(e,'',true)}<figcaption>${esc(e.imageAlt||e.title)}${imageCredit?`<span>Foto: <a href="${esc(safeUrl(imageCredit.sourceUrl))}" target="_blank" rel="noopener">${esc(imageCredit.author)}</a> · <a href="${esc(safeUrl(imageCredit.licenseUrl))}" target="_blank" rel="noopener">${esc(imageCredit.license)}</a></span>`:''}</figcaption></figure><div class="article-layout"><div class="article-body"><span class="eyebrow">MENGENAL ${esc(e.title.toUpperCase())}</span>${(e.paragraphs||[e.summary]).map(t=>`<p>${esc(t)}</p>`).join('')}${e.steps?.length?`<section class="practice-section"><h2>${e.category==='permainan'?'Cara bermain':'Langkah pengenalan'}</h2><ol class="practice-steps">${e.steps.map(s=>`<li><h3>${esc(s.title)}</h3><p>${esc(s.body)}</p></li>`).join('')}</ol></section>`:['tari','musik','kerajinan'].includes(e.category)?notice('Materi ini berupa pengenalan. Kami belum menyediakan video tutorial untuk topik ini.'+(site.publicPreview?'':' Kamu dapat mengajukan request jika ingin mempelajarinya lebih lanjut.')) :''}${e.mapQuery?button('Lihat lokasi di peta','https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(e.mapQuery),'btn-outline','upRight'):''}<div class="source-note" id="sumber"><span class="eyebrow">SUMBER MATERI</span><a href="${esc(safeUrl(e.sourceUrl))}" target="_blank" rel="noopener noreferrer">${esc(e.sourceLabel||'Baca sumber rujukan')}${icon('upRight')}</a>${(e.sources||[]).filter(source=>source.url!==e.sourceUrl).map(source=>`<a href="${esc(safeUrl(source.url))}" target="_blank" rel="noopener">${esc(source.label)}${icon('upRight')}</a>`).join('')}<p>Kami menulis pengenalan ini dengan merujuk sumber tersebut.${site.publicPreview?'':` Punya koreksi? <a href="${requestLink(e.provinceId,e.category)}&topik=${encodeURIComponent('Koreksi: '+e.title)}">Beri tahu pengelola.</a>`}</p></div></div><aside class="article-sidebar">${e.facts?.length?`<div class="fact-list"><h2>Catatan singkat</h2>${e.facts.map(f=>`<div><span>${esc(f.label)}</span><p>${esc(f.value)}</p></div>`).join('')}</div>`:''}<div class="mentor-note">${icon('user')}<h3>Ingin belajar dengan pendamping?</h3><p>${site.publicPreview?'Kami belum membuka layanan pendampingan. Kamu bisa membaca pengenalan dan sumber rujukannya.':'Kami sedang menyiapkan jejaring praktisi dan sanggar. Kamu dapat mengajukan kebutuhan belajar.'}</p>${button('Request pendamping',requestLink(e.provinceId,e.category)+'&tujuan=pendamping&topik='+encodeURIComponent(e.title),'btn-dark')}</div></aside></div></div></article>${related.length?`<section class="related-section wrap"><div class="section-heading"><div><span class="eyebrow">MASIH DI ${esc(p?.name.toUpperCase())}</span><h2>Lanjut mengenal daerahnya.</h2></div></div><div class="featured-grid">${related.map(e=>entryCard(e,data.provinces)).join('')}</div></section>`:''}`;
}
function safeUrl(url){try{const u=new URL(url);return ['https:','http:'].includes(u.protocol)?u.href:'#'}catch{return '#'}}

function requestPage(params){
 if(site.publicPreview)return publicFeaturePage('Request');
 let draft={};try{draft=JSON.parse(sessionStorage.getItem('swaranusa-draft')||'{}')}catch{}
 if(draft._context!==location.search)draft={};
 const pid=draft.provinceId??params.get('provinsi')??'',category=draft.category??params.get('kategori')??'';
 const requestedPurpose=draft.purpose??params.get('tujuan')??'informasi';
 const purpose=['informasi','pendamping'].includes(requestedPurpose)?requestedPurpose:'informasi',topic=draft.topic??params.get('topik')??'';
 return `<section class="request-page wrap">${crumb([['Ajukan request']])}<div class="request-intro"><span class="eyebrow">KAMU INGIN BELAJAR APA?</span><h1>Mulai dari<br>kebutuhanmu.</h1><p>Sebutkan topik yang belum kamu temukan.<br> Pengelola akan memeriksa request sebelum meneruskannya.</p><div class="request-how"><div><span>01</span><p>Tulis kebutuhanmu.</p></div><div><span>02</span><p>Pengelola meninjau request.</p></div><div><span>03</span><p>Lihat tanggapan di akunmu.</p></div></div><p class="quiet-note">Belum ada jaminan waktu atau pendamping yang cocok. Kamu bisa memantau status dari halaman akun.</p></div><form class="request-form" id="request-form"><h2>Detail request</h2><fieldset class="purpose-select"><legend>Yang kamu butuhkan</legend><label class="purpose-option"><input type="radio" name="purpose" value="informasi" ${purpose==='informasi'?'checked':''}>${icon('book')}<span>Materi / informasi<small>Usulkan topik atau lengkapi informasi.</small></span></label><label class="purpose-option"><input type="radio" name="purpose" value="pendamping" ${purpose==='pendamping'?'checked':''}>${icon('user')}<span>Pendamping belajar<small>Cari praktisi sesuai kebutuhanmu.</small></span></label></fieldset><div class="form-row"><label>Provinsi<select name="provinceId" required><option value="">Pilih provinsi</option>${data.provinces.map(p=>`<option value="${p.id}" ${pid===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Kategori<select name="category" required><option value="">Pilih kategori</option>${Object.entries(cats).map(([id,name])=>`<option value="${id}" ${category===id?'selected':''}>${name}</option>`).join('')}</select></label></div><label>Topik yang kamu cari<input name="topic" minlength="3" maxlength="140" value="${esc(topic)}" placeholder="Contoh: pengenalan musik Saluang" required></label><label>Ceritakan kebutuhanmu<textarea name="description" minlength="10" maxlength="3000" rows="4" placeholder="Apa yang ingin kamu ketahui atau pelajari?" required>${esc(draft.description||'')}</textarea></label><div class="mentor-fields" ${purpose!=='pendamping'?'hidden':''}><div class="form-row"><label>Kota yang diharapkan<input name="city" minlength="2" maxlength="120" value="${esc(draft.city||'')}" placeholder="Contoh: Padang" ${purpose==='pendamping'?'required':''}></label><label>Bentuk pendampingan<select name="format"><option value="fleksibel">Fleksibel</option><option value="daring" ${draft.format==='daring'?'selected':''}>Daring</option><option value="tatap-muka" ${draft.format==='tatap-muka'?'selected':''}>Tatap muka</option></select></label></div><label>Waktu yang diharapkan <span class="optional">opsional</span><input name="timePreference" maxlength="200" value="${esc(draft.timePreference||'')}" placeholder="Contoh: akhir pekan bulan depan"></label><p class="field-help">Kamu dan pendamping membahas biaya, waktu, serta tempat setelah cocok.</p></div><label class="checkbox-label"><input type="checkbox" name="consent" required ${draft.consent?'checked':''}><span>Saya setuju pengelola dan ahli terkait membaca ringkasan kebutuhan ini. Mereka tidak akan melihat kontak pribadi saya melalui daftar request.</span></label>${formError()}<button class="btn btn-dark submit-wide" type="submit">${user?'Kirim request':'Masuk dan kirim request'}${icon('arrow')}</button><p class="field-help">${user?`Kamu masuk sebagai ${esc(user.name)}.`:'Kamu perlu masuk untuk mengirim dan melacak request. Isianmu tetap tersimpan saat masuk.'}</p></form></section>`;
}
function mentorsPage(){return `<section class="wrap mentors-page">${crumb([['Pendamping']])}<div class="page-heading"><span class="eyebrow">BELAJAR DENGAN PRAKTISI</span><h1>Temukan orang yang<br>memahami budayanya.</h1><p>Kamu dapat meminta bantuan pelatih, perajin, atau sanggar sesuai kebutuhan belajar.</p></div><div class="mentors-layout"><div class="mentor-photo"><img src="/assets/hero-sumbar.jpg" alt="Arsitektur Istano Basa Pagaruyung di Sumatera Barat"><span>Belajar bersama masyarakat setempat.</span></div><div class="mentor-empty"><span class="eyebrow">JEJARING PENDAMPING</span><h2>Kami sedang mencari<br>praktisi dan sanggar.</h2><p>${site.publicPreview?'Belum ada mitra yang membuka layanan di SwaraNusa. Pendaftaran dan request pendamping belum tersedia pada situs publik ini.':'Belum ada mitra yang membuka layanan di SwaraNusa. Kamu tetap bisa mengirim request pendamping agar pengelola mengetahui kebutuhanmu.'}</p>${button('Request pendamping','/request?tujuan=pendamping','btn-dark')}<p class="field-help">Pendampingan dapat berbayar sesuai kesepakatan langsung. SwaraNusa belum menangani pembayaran dan pemesanan.</p></div></div></section>`}
function aboutPage(){
 const steps=[['compass','Pilih daerah yang ingin kamu kenal.','Buka salah satu dari 10 provinsi. Kamu bisa beralih daerah kapan saja.'],['book','Tentukan kegiatanmu.','Pilih seni, wisata, kuliner, atau permainan. Setiap materi diberi penanda pengenalan atau panduan.'],['globe','Baca dan lanjutkan sesuai kebutuhan.',site.publicPreview?'Buka sumber rujukannya, lalu coba panduan permainan yang tersedia.':'Baca sumber, coba panduan yang tersedia, atau ajukan request materi dan pendamping.']];
 return `<section class="wrap about-page">${crumb([['Tentang SwaraNusa']])}
  <div class="about-heading"><div><span class="eyebrow label-pill">${icon('leaf')} TENTANG SWARANUSA</span><h1>Kenali daerah,<br><em>pahami budayanya.</em></h1><p>Kami menyusun pengenalan budaya Sumatra agar kamu punya tempat untuk mulai belajar.</p><div class="about-facts"><span>${icon('compass')}${data.provinces.length} provinsi</span><span>${icon('book')}${data.entries.length} materi tersedia</span></div><a class="text-link" href="#belajar">Lihat cara belajarnya ${icon('arrow')}</a></div><div class="about-logo-frame"><img class="about-logo" src="/assets/logo.jpg" alt="Logo SwaraNusa, Warisan Budaya Sumatera"><span>${icon('pin')} Sumatra dan kepulauan sekitarnya</span></div></div>
  <div class="about-columns"><section class="surface-panel about-learning" id="belajar"><div class="panel-top">${surfaceIcon('compass')}<span class="eyebrow">CARA BELAJAR</span></div><h2>Mulai dengan<br>satu provinsi.</h2><p>Pilih daerahnya, lalu tentukan apa yang ingin kamu baca.</p><ol class="learning-steps">${steps.map(([ico,title,copy],i)=>`<li>${surfaceIcon(ico)}<div><span class="step-label">LANGKAH ${String(i+1).padStart(2,'0')}</span><h3>${title}</h3><p>${copy}</p></div></li>`).join('')}</ol>${button('Pilih provinsi','/#provinsi','btn-dark')}</section>
   <div class="about-side-stack" id="batas-layanan"><section class="surface-panel about-collection"><div class="panel-top">${surfaceIcon('book')}<span class="eyebrow">KOLEKSI BACAAN</span></div><h2>Kenali cerita<br>di balik budayanya.</h2><p>Provinsi membantu kamu menelusuri materi. Satu tradisi dapat hidup di beberapa wilayah dan memiliki variasi antarkomunitas.</p><div class="availability-note">${icon('info')}<p>${site.publicPreview?'Koleksi masih dalam tahap pengisian. Beberapa kategori belum terisi dan belum memenuhi lima materi per kategori.':'Akun demo memperagakan alur request dalam proyek pembelajaran. Profil ahli demo bukan mitra yang bisa kamu hubungi.'}</p></div><a class="text-link" href="#sumber">Tentang sumber materi ${icon('arrow')}</a></section>
   <section class="surface-panel about-companions"><div class="panel-top">${surfaceIcon('user','gold')}<span class="eyebrow">PENDAMPING BELAJAR</span></div><h2>Belajar bersama praktisi.</h2><p>${site.publicPreview?'Pendaftaran akun dan request pendamping belum dibuka pada situs publik ini. Kamu tetap bisa membaca materi dan rujukannya.':'Untuk mengirim dan memantau request pendamping, masuk melalui akunmu.'}</p><p>Biaya dan jadwal disepakati langsung dengan pendamping. SwaraNusa belum menangani pembayaran atau reservasi.</p><a class="text-link" href="/pendamping">Tentang pendamping ${icon('arrow')}</a></section></div></div>
  <section class="sources-section about-sources" id="sumber"><div class="section-heading"><div><span class="eyebrow label-pill">${icon('globe')} SUMBER & ATRIBUSI</span><h2>Ada rujukan<br><em>untuk kamu baca.</em></h2></div><p>Tautan sumber ada di setiap materi.<br>Kredit foto mencatat pemilik dan lisensinya.</p></div><div class="source-links"><a href="https://ich.unesco.org/en/lists?USL=00509" target="_blank" rel="noopener">${surfaceIcon('globe')}<span><strong>UNESCO</strong><small>Dokumentasi warisan budaya takbenda.</small></span>${icon('upRight')}</a><a href="https://www.indonesia.travel/id/id/destination/sumatra" target="_blank" rel="noopener">${surfaceIcon('pin')}<span><strong>Indonesia Travel</strong><small>Pengenalan daerah dan tujuan wisata.</small></span>${icon('upRight')}</a><a href="/credits.html">${surfaceIcon('image','gold')}<span><strong>Kredit foto & rujukan</strong><small>Pemilik, sumber, dan lisensi foto.</small></span>${icon('upRight')}</a></div></section>
  <section class="about-help" id="bantuan">${surfaceIcon('chat')}<div><h2>Menemukan informasi yang keliru?</h2><p>${site.publicPreview?'Formulir koreksi belum dibuka pada situs publik ini.':'Sertakan judul materi dan sumber pembanding agar pengelola dapat memeriksanya.'}</p></div>${button('Kirim koreksi','/request?topik=Koreksi%20informasi','btn-outline')}</section></section>`;
}
function notFound(){return `<section class="wrap error-page"><span class="eyebrow">HALAMAN TIDAK DITEMUKAN</span><h1>Kembali pilih daerah?</h1><p>Tautan ini belum mengarah ke halaman SwaraNusa yang tersedia.</p>${button('Buka beranda','/','btn-dark')}</section>`}

function requestItem(r){return `<a class="request-item" href="/request/${esc(r.id)}"><div><div class="request-item-meta"><span>${esc(province(r.provinceId)?.name)} / ${esc(cats[r.category])}</span><time>${date(r.createdAt)}</time></div><h3>${esc(r.topic)}</h3><p>${r.purpose==='pendamping'?'Pendamping belajar':'Materi / informasi'}${user?.role!=='user'?` · ${esc(r.userName||'Pengguna')}`:''}</p></div><div>${statusBadge(r.status)}${icon('chevron')}</div></a>`}
async function accountPage(params){
 if(!user)return `<section class="wrap account-page">${empty('Masuk untuk melihat request kamu.','Dari sini kamu bisa membaca tanggapan dan mengikuti perubahan status.')}<button class="btn btn-dark" data-auth>Masuk ke akun ${icon('arrow')}</button></section>`;
 const [r,n]=await Promise.all([api('/requests'),api('/notifications')]);requestCache=r.requests;notifications=n.notifications;
 const isNotifications=params.get('bagian')==='notifikasi';
 const heading={user:['Catatan belajarmu.','Ikuti request dan baca tanggapan dari pengelola.'],admin:['Ruang pengelola.','Periksa request sebelum meneruskannya ke ahli.'],expert:['Ruang pendamping.','Baca kebutuhan pengguna sesuai bidang layanan.']}[user.role];
 return `<section class="wrap account-page"><div class="account-heading"><div><span class="eyebrow">AKUN / ${formatRole(user.role).toUpperCase()}${user.isDemo?' DEMO':''}</span><h1>${heading[0]}</h1><p>${heading[1]}</p></div><button class="text-link" data-logout>Keluar ${icon('logout')}</button></div>${user.isDemo?notice('Kamu memakai akun demo untuk mencoba alur layanan. Profil dan tanggapan demo bukan penawaran dari pendamping nyata.'):''}<div class="account-tabs"><a href="/akun" class="${!isNotifications?'active':''}">${icon('list')}${user.role==='user'?'Request saya':'Daftar request'} <span>${requestCache.length}</span></a><a href="/akun?bagian=notifikasi" class="${isNotifications?'active':''}">${icon('bell')}Notifikasi <span>${notifications.filter(n=>!n.read).length}</span></a>${user.role==='user'?button('Buat request','/request','btn-dark'):''}</div>${isNotifications?`<div class="notifications-list">${notifications.length?`<button class="text-link" data-read-notifications>Tandai semua sudah dibaca ${icon('check')}</button>${notifications.map(n=>`<a class="notification-item ${n.read?'read':''}" href="/request/${esc(n.requestId)}">${icon('bell')}<div><p>${esc(n.message)}</p><time>${date(n.createdAt)}</time></div>${!n.read?'<span class="unread-dot"></span>':''}</a>`).join('')}`:empty('Belum ada notifikasi.','Kami menampilkan kabar di sini ketika status request berubah.')}</div>`:`<div class="request-list">${requestCache.length?requestCache.map(requestItem).join(''):empty(user.role==='user'?'Belum ada request.':'Belum ada request yang perlu ditangani.',user.role==='expert'?'Pengelola akan meneruskan request yang sesuai setelah meninjaunya.':'Kamu bisa mulai dengan menyebutkan topik yang ingin kamu pelajari.',user.role==='user'?'/request':'')}</div>`}<div class="demo-switch"><span>Coba peran lain dalam demo:</span><button data-demo="user">Pengunjung</button><button data-demo="expert">Pendamping</button><button data-demo="admin">Pengelola</button></div></section>`;
}
async function requestDetail(id){
 if(!user)return `<section class="wrap account-page">${empty('Masuk untuk membuka request.','Pemilik request dan pihak yang menangani dapat melihat informasi di halaman ini.')}<button class="btn btn-dark" data-auth>Masuk ke akun ${icon('arrow')}</button></section>`;
 const {request:r}=await api('/requests/'+encodeURIComponent(id));const own=r.userId===user.id;
 const active=['pending','open','responded','connected'].includes(r.status);
 const actionButton=(label,action,cls='btn-outline',rid='')=>`<button class="btn ${cls}" data-request-action="${action}" data-request-id="${esc(r.id)}" ${rid?`data-response-id="${esc(rid)}"`:''}>${label}${icon(action==='approve'||action==='complete'?'check':'arrow')}</button>`;
 const canRespond=(user.role==='expert'&&r.purpose==='pendamping'||user.role==='admin'&&r.purpose==='informasi')&&['open','responded'].includes(r.status);
 const responses=r.responses||[],historyItems=r.history||[];
 return `<section class="wrap request-detail">${crumb([['Akun','/akun'],['Detail request']])}<div class="request-detail-heading"><div><span class="eyebrow">${r.purpose==='pendamping'?'PENDAMPING BELAJAR':'MATERI / INFORMASI'} / ${esc(String(r.id).slice(0,8))}</span><h1>${esc(r.topic)}</h1><div class="article-meta">${icon('pin')}${esc(province(r.provinceId)?.name)}<span>·</span>${esc(cats[r.category])}<span>·</span>${date(r.createdAt)}</div></div>${statusBadge(r.status)}</div><div class="request-detail-grid"><div><section class="detail-section"><h2>Kebutuhan belajar</h2><p class="preserve-lines">${esc(r.description)}</p>${r.purpose==='pendamping'?`<dl class="request-facts"><div><dt>Kota</dt><dd>${esc(r.city)}</dd></div><div><dt>Bentuk</dt><dd>${esc({daring:'Daring','tatap-muka':'Tatap muka',fleksibel:'Fleksibel'}[r.format]||r.format)}</dd></div>${r.timePreference?`<div><dt>Waktu</dt><dd>${esc(r.timePreference)}</dd></div>`:''}</dl>`:''}</section><section class="detail-section"><h2>Tanggapan <span class="count-light">${responses.length}</span></h2>${responses.length?responses.map(a=>`<div class="response-item"><div class="response-author"><span class="avatar">${esc(a.expertName?.charAt(0)||'P')}</span><div><strong>${esc(a.expertName||'Pengelola')}</strong><small>${a.isDemo?'Akun demo · ':''}${date(a.createdAt)}</small></div>${r.selectedResponseId===a.id?'<span class="selected-label">Terpilih</span>':''}</div><p class="preserve-lines">${esc(a.message)}</p>${own&&r.purpose==='pendamping'&&['open','responded'].includes(r.status)?actionButton('Pilih pendamping ini','select','btn-dark',a.id):''}${own&&r.selectedResponseId===a.id&&r.status==='connected'?notice('Kamu memilih profil demo. Profil ini memperagakan alur dan tidak memiliki kontak layanan nyata. Pada layanan dengan mitra, kamu dapat membuka kontak publik yang telah disetujui pendamping.'):''}</div>`).join(''):`<p class="quiet-note">${r.status==='pending'?'Pengelola belum meninjau request ini.':r.status==='rejected'?'Pengelola menolak request ini. Baca alasannya pada riwayat.':['cancelled','completed'].includes(r.status)?'Request ini sudah ditutup.':'Belum ada tanggapan. Kamu dapat memantau kabarnya di sini.'}</p>`}${canRespond?`<form class="response-form" data-response-form="${esc(r.id)}"><label>Tulis tanggapan<textarea name="message" rows="4" minlength="10" maxlength="3000" required placeholder="Jelaskan informasi atau bentuk pendampingan yang dapat kamu bantu."></textarea></label>${formError()}<button class="btn btn-dark" type="submit">Kirim tanggapan ${icon('arrow')}</button></form>`:''}</section></div><aside><section class="request-status-panel"><h2>Status request</h2><ol class="status-history">${historyItems.map(h=>`<li><span>${esc(statusLabels[h.status]||h.status)}</span><time>${date(h.createdAt)}</time>${h.note?`<p>${esc(h.note)}</p>`:''}</li>`).join('')}</ol><div class="request-actions">${user.role==='admin'&&r.status==='pending'?`${actionButton('Setujui request','approve','btn-dark')}<form class="reject-form" data-reject-form="${esc(r.id)}"><label>Alasan penolakan<textarea name="note" minlength="3" maxlength="1000" rows="2" required placeholder="Jelaskan agar pemohon memahami alasannya."></textarea></label>${formError()}<button class="btn btn-outline" type="submit">Tolak request</button></form>`:''}${own&&r.status==='connected'?`${actionButton('Tandai selesai','complete','btn-dark')}${actionButton('Cari pendamping lain','reopen')}`:''}${user.role==='admin'&&r.purpose==='informasi'&&r.status==='responded'&&responses.length>0?actionButton('Tandai selesai','complete','btn-dark'):''}${own&&active?actionButton('Batalkan request','cancel','btn-quiet'):''}</div></section><p class="field-help">Kamu dapat membuka kembali pencarian jika pendamping yang kamu pilih belum cocok. Biaya dan jadwal mengikuti kesepakatan langsung.</p></aside></div></section>`;
}

async function render(){
 disposeCarousels();disposeCarousels=()=>{};
 const v=++pageVersion;const path=routePath(location.pathname).replace(/\/$/,'')||'/',params=new URLSearchParams(location.search);
 let content,asyncRoute=false;
 if(path==='/')content=home();
 else if(path.startsWith('/provinsi/'))content=provincePage(decodeURIComponent(path.split('/')[2]),params);
 else if(path.startsWith('/materi/'))content=entryPage(decodeURIComponent(path.split('/')[2]));
 else if(path==='/request')content=requestPage(params);
 else if(path==='/pendamping')content=mentorsPage();
 else if(path==='/tentang')content=aboutPage();
 else if(site.publicPreview&&(path==='/akun'||path.startsWith('/request/')))content=publicFeaturePage(path==='/akun'?'Akun':'Request');
 else if(path==='/akun'||path.startsWith('/request/')){asyncRoute=true;app.innerHTML=header()+`<main id="main" tabindex="-1"><div class="wrap route-loading" role="status">Memuat ${path==='/akun'?'akun':'request'}…</div></main>`+footer();try{content=await(path==='/akun'?accountPage(params):requestDetail(decodeURIComponent(path.split('/')[2])))}catch(e){content=`<section class="wrap account-page">${empty('Halaman belum bisa dibuka.',esc(e.message),'/akun','Kembali ke akun')}</section>`}}
 else content=notFound();
 if(v!==pageVersion)return;
 app.innerHTML=header()+`<main id="main" tabindex="-1">${content}</main>`+footer();
 const pageTitles={'/':'Kenali budaya Sumatra','/request':'Ajukan request','/akun':'Akun','/pendamping':'Pendamping','/tentang':'Tentang'};
 preparePageLinks();disposeCarousels=mountCarousels(app);setupMotion();
 document.title=`${pageTitles[path]||document.querySelector('h1')?.textContent||'SwaraNusa'} | SwaraNusa`;
 if(location.hash){requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView({behavior:'instant'}))}
 document.querySelectorAll('a[href^="http"]').forEach(a=>{a.target='_blank';a.rel='noopener noreferrer'});
 document.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{img.classList.add('image-unavailable');img.removeAttribute('src')},{once:true}));
}
function toast(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('visible');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>t.classList.remove('visible'),4500)}
async function refreshSession(){if(site.publicPreview){user=null;notifications=[];return;}const d=await api('/session');user=d.user;if(user)try{notifications=(await api('/notifications')).notifications}catch{notifications=[]}else notifications=[]}
let authSuccess=null;
function openAuth(mode='login',after=null){if(site.publicPreview){route('/akun');return;}authSuccess=after;fillAuth(mode);if(!dialog.open)dialog.showModal()}
function fillAuth(mode){dialog.innerHTML=`<button class="icon-btn dialog-close" data-close-dialog aria-label="Tutup">${icon('close')}</button><span class="eyebrow">AKUN SWARANUSA</span><h2 id="auth-title">${mode==='register'?'Buat akunmu.':'Selamat datang.'}</h2><p>${mode==='register'?'Simpan request dan ikuti tanggapannya.':'Masuk untuk melanjutkan request kamu.'}</p><form id="auth-form" data-mode="${mode}">${mode==='register'?'<label>Nama<input name="name" autocomplete="name" minlength="2" maxlength="80" required></label>':''}<label>Email<input name="email" type="email" autocomplete="email" required maxlength="254"></label><label>Kata sandi<input name="password" type="password" autocomplete="${mode==='register'?'new-password':'current-password'}" minlength="8" maxlength="128" required>${mode==='register'?'<small>Gunakan sedikitnya 8 karakter.</small>':''}</label>${formError()}<button class="btn btn-dark submit-wide" type="submit">${mode==='register'?'Daftar':'Masuk'}${icon('arrow')}</button></form><p class="auth-switch">${mode==='register'?'Sudah punya akun?':'Belum punya akun?'} <button data-auth-mode="${mode==='register'?'login':'register'}">${mode==='register'?'Masuk':'Daftar'}</button></p><div class="auth-demo"><span class="small-label">COBA ALUR PROYEK</span><p>Akun demo menyimpan contoh aktivitas di pratinjau ini.</p><div><button data-demo="user">Pengunjung</button><button data-demo="expert">Pendamping</button><button data-demo="admin">Pengelola</button></div></div>`}
function saveDraft(form){const value=getValues(form);value.consent=form.elements.consent.checked;value._context=location.search;sessionStorage.setItem('swaranusa-draft',JSON.stringify(value))}
async function sendRequest(form){const body=getValues(form);body.consent=form.elements.consent.checked;const d=await post('/requests',body);sessionStorage.removeItem('swaranusa-draft');toast('Request kamu sudah masuk. Pengelola akan meninjaunya.');route('/request/'+d.request.id)}
async function submitWithState(form,task){const submit=form.querySelector('[type="submit"]'),error=form.querySelector('.form-error');if(error){error.hidden=true;error.textContent=''}if(submit)submit.disabled=true;try{await task()}catch(e){if(error){error.textContent=e.message;error.hidden=false}else toast(e.message)}finally{if(submit)submit.disabled=false}}

document.addEventListener('click',async event=>{
 const navTrigger=event.target.closest('[data-nav-dropdown]');if(navTrigger){toggleNavDropdown(navTrigger);return;}
 if(!event.target.closest('.nav-dropdown'))closeNavDropdowns();
 if(!event.target.closest('.site-header'))closeMobileMenu();
 const a=event.target.closest('a');
 if(a&&a.origin===location.origin&&!a.hasAttribute('download')&&!event.metaKey&&!event.ctrlKey&&!event.shiftKey&&a.target!=='_blank'&& !a.pathname.match(/\.(html|pdf|jpg|png|md)$/)){
 event.preventDefault();const url=routePath(a.pathname)+a.search+a.hash;if(a.pathname===location.pathname&&a.search===location.search&&a.hash){history.pushState({},'',siteUrl(url));document.getElementById(a.hash.slice(1))?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});if(a.hash==='#main')document.getElementById('main')?.focus({preventScroll:true});closeMobileMenu();return}route(url);return}
 const el=event.target.closest('button');if(!el)return;
 if(el.hasAttribute('data-auth'))return openAuth('login',()=>{render()});
 if(el.hasAttribute('data-close-dialog'))return dialog.close();
 if(el.dataset.authMode)return fillAuth(el.dataset.authMode);
 if(el.hasAttribute('data-menu')){const nav=document.querySelector('.mobile-nav');nav.hidden=!nav.hidden;el.setAttribute('aria-expanded',String(!nav.hidden));el.setAttribute('aria-label',nav.hidden?'Buka menu':'Tutup menu');return}
 if(el.hasAttribute('data-logout')){try{await post('/auth/logout');user=null;notifications=[];route('/');toast('Kamu sudah keluar.')}catch(e){toast(e.message)}return}
 if(el.dataset.demo){el.disabled=true;try{const d=await post('/auth/demo',{role:el.dataset.demo});user=d.user;await refreshSession();const next=authSuccess;authSuccess=null;dialog.close();if(next)await next();else route('/akun');toast(`Kamu memakai akun ${formatRole(user.role).toLowerCase()} demo.`)}catch(e){toast(e.message)}finally{el.disabled=false}return}
 if(el.hasAttribute('data-read-notifications')){try{await post('/notifications/read');await refreshSession();render()}catch(e){toast(e.message)}return}
 if(el.dataset.requestAction){const action=el.dataset.requestAction;if(action==='cancel'&&!confirm('Batalkan request ini? Pengguna lain tidak dapat menambahkan tanggapan setelah kamu membatalkannya.'))return;el.disabled=true;try{await post('/requests/'+el.dataset.requestId+'/action',{action,responseId:el.dataset.responseId});await refreshSession();await render();toast({approve:'Request sudah terbuka.',cancel:'Request sudah kamu batalkan.',select:'Kamu sudah memilih pendamping.',reopen:'Pencarian pendamping kembali terbuka.',complete:'Request sudah selesai.'}[action]||'Status request diperbarui.')}catch(e){toast(e.message);el.disabled=false}}
});
document.addEventListener('change',event=>{const form=event.target.closest('#request-form');if(!form)return;if(event.target.name==='purpose'){const on=form.elements.purpose.value==='pendamping';form.querySelector('.mentor-fields').hidden=!on;form.elements.city.required=on;}saveDraft(form)});
document.addEventListener('input',event=>{const form=event.target.closest('#request-form');if(form)saveDraft(form)});
document.addEventListener('submit',event=>{
 const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();
 if(form.id==='auth-form')return submitWithState(form,async()=>{const d=await post('/auth/'+form.dataset.mode,getValues(form));user=d.user;await refreshSession();const next=authSuccess;authSuccess=null;dialog.close();if(next)await next();else render()});
 if(form.id==='request-form'){saveDraft(form);if(!user){openAuth('login',()=>submitWithState(form,()=>sendRequest(form)));return}return submitWithState(form,()=>sendRequest(form))}
 if(form.dataset.responseForm)return submitWithState(form,async()=>{await post('/requests/'+form.dataset.responseForm+'/responses',getValues(form));await refreshSession();await render();toast('Tanggapan sudah tersimpan.')});
 if(form.dataset.rejectForm)return submitWithState(form,async()=>{await post('/requests/'+form.dataset.rejectForm+'/action',{action:'reject',...getValues(form)});await refreshSession();await render();toast('Request ditolak dengan alasan.');});
});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
dialog.addEventListener('close',()=>{authSuccess=null});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){const open=document.querySelector('[data-nav-dropdown][aria-expanded="true"]');if(open){event.preventDefault();closeNavDropdowns(true);}else if(document.querySelector('.mobile-nav:not([hidden])')){event.preventDefault();closeMobileMenu(true);}}else if(event.key==='ArrowDown'&&event.target.matches('[data-nav-dropdown]')){event.preventDefault();if(event.target.getAttribute('aria-expanded')==='true')document.getElementById(event.target.getAttribute('aria-controls'))?.querySelector('a')?.focus();else toggleNavDropdown(event.target,true);}});
document.addEventListener('focusout',event=>{const dropdown=event.target.closest('.nav-dropdown');if(dropdown&&event.relatedTarget&&!dropdown.contains(event.relatedTarget))closeNavDropdowns();});
window.addEventListener('scroll',()=>closeNavDropdowns(),{passive:true});
window.addEventListener('resize',()=>{closeNavDropdowns();closeMobileMenu();},{passive:true});
window.addEventListener('popstate',render);
async function boot(){try{const response=await fetch(siteUrl('/data.json'));if(!response.ok)throw new Error('Koleksi belum bisa dimuat.');data=await response.json();await refreshSession();await render()}catch(e){app.innerHTML=header()+`<main id="main" class="wrap error-page"><h1>SwaraNusa belum bisa dimuat.</h1><p>${esc(e.message)}</p><a class="btn btn-dark" href="/">Coba lagi</a></main>`+footer();preparePageLinks()}}
boot();
